-- =============================================================================================
-- Hand-written below this line: configuration checks, opening hours that never overlap,
-- closures that never cover a live booking, bookings made only in whole slots inside opening
-- hours, outside closures, within the notice and advance windows, the per-unit limit and the
-- facility's capacity (all under a per-facility lock), the approval decided by the facility,
-- numbering per property, the allowed status transitions with the reasons they need,
-- timestamps owned by the database, append-only history written by the database, row-level
-- security and grants. See docs/architecture/DATA_MODEL.md section 8 (Facilities).
-- =============================================================================================

-- ---------------------------------------------------------------------------------------------
-- Checks
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "facilities" ADD CONSTRAINT "facilities_settings"
  CHECK ("slot_minutes" BETWEEN 5 AND 1440 AND "slot_minutes" % 5 = 0
         AND "capacity" BETWEEN 1 AND 1000
         AND "min_notice_minutes" BETWEEN 0 AND 525600
         AND "max_advance_days" BETWEEN 1 AND 730
         AND "max_slots_per_booking" BETWEEN 1 AND 288
         AND ("max_upcoming_per_unit" IS NULL OR "max_upcoming_per_unit" BETWEEN 1 AND 100)
         AND "cancellation_minutes" BETWEEN 0 AND 525600);
ALTER TABLE "facilities" ADD CONSTRAINT "facilities_text"
  CHECK ("description" IS NULL
         OR ("description" = btrim("description") AND length("description") BETWEEN 1 AND 2000));
ALTER TABLE "facilities" ADD CONSTRAINT "facilities_archived"
  CHECK (("status" = 'ARCHIVED') = ("archived_at" IS NOT NULL));

ALTER TABLE "facility_opening_hours" ADD CONSTRAINT "facility_opening_hours_range"
  CHECK ("weekday" BETWEEN 1 AND 7 AND "closes_at" > "opens_at");

ALTER TABLE "facility_closures" ADD CONSTRAINT "facility_closures_range"
  CHECK ("ends_at" > "starts_at");
ALTER TABLE "facility_closures" ADD CONSTRAINT "facility_closures_text"
  CHECK ("reason" = btrim("reason") AND length("reason") BETWEEN 1 AND 500);
ALTER TABLE "facility_closures" ADD CONSTRAINT "facility_closures_lifted"
  CHECK (("lifted_at" IS NULL) = ("lifted_by_user_id" IS NULL));

ALTER TABLE "facility_bookings" ADD CONSTRAINT "facility_bookings_range"
  CHECK ("ends_at" > "starts_at");
ALTER TABLE "facility_bookings" ADD CONSTRAINT "facility_bookings_number_set"
  CHECK ("booking_number" IS NOT NULL AND "booking_number" >= 1 AND "slot_count" >= 1);
ALTER TABLE "facility_bookings" ADD CONSTRAINT "facility_bookings_text"
  CHECK (("purpose" IS NULL OR ("purpose" = btrim("purpose") AND length("purpose") BETWEEN 1 AND 200))
         AND ("status_note" IS NULL
              OR ("status_note" = btrim("status_note") AND length("status_note") BETWEEN 1 AND 1000)));
ALTER TABLE "facility_bookings" ADD CONSTRAINT "facility_bookings_dates"
  CHECK (("status" <> 'CANCELLED' OR "cancelled_at" IS NOT NULL)
         AND ("status" <> 'REJECTED' OR "decided_at" IS NOT NULL)
         AND ("decided_at" IS NULL) = ("decided_by_user_id" IS NULL));

ALTER TABLE "facility_booking_events" ADD CONSTRAINT "facility_booking_events_note"
  CHECK ("note" IS NULL OR ("note" = btrim("note") AND length("note") BETWEEN 1 AND 1000));

-- Serialises everything that changes what a facility can take: bookings, closures, hours.
CREATE FUNCTION app_facility_lock(facility uuid) RETURNS void
  LANGUAGE sql
  AS $$ SELECT pg_advisory_xact_lock(hashtextextended('veyra.facility:' || facility::text, 0)) $$;

-- ---------------------------------------------------------------------------------------------
-- Facilities: for an active common area; archived once nothing is still booked; final.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app_facility_insert() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW."status" <> 'ACTIVE' THEN
    RAISE EXCEPTION 'facilities start active' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM "properties" WHERE "id" = NEW."property_id" AND "status" = 'ARCHIVED') THEN
    RAISE EXCEPTION 'the property is archived' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "common_areas" WHERE "id" = NEW."common_area_id" AND "status" = 'ACTIVE') THEN
    RAISE EXCEPTION 'the common area is archived' USING ERRCODE = 'check_violation';
  END IF;
  NEW."created_at" := now();
  NEW."archived_at" := NULL;
  RETURN NEW;
END
$$;

CREATE TRIGGER "facilities_insert"
  BEFORE INSERT ON "facilities"
  FOR EACH ROW EXECUTE FUNCTION app_facility_insert();

CREATE FUNCTION app_facility_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF OLD."status" = 'ARCHIVED' THEN
    RAISE EXCEPTION 'facility % is archived and no longer changes', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."common_area_id", NEW."created_at")
     IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."common_area_id", OLD."created_at") THEN
    RAISE EXCEPTION 'facility % cannot move to another common area', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  NEW."archived_at" := OLD."archived_at";
  IF NEW."status" = 'ARCHIVED' THEN
    PERFORM app_facility_lock(OLD."id");
    IF EXISTS (SELECT 1 FROM "facility_bookings" WHERE "facility_id" = OLD."id"
                  AND "status" IN ('PENDING', 'CONFIRMED') AND "ends_at" > now()) THEN
      RAISE EXCEPTION 'cancel the upcoming bookings of this facility before archiving it'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW."archived_at" := now();
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "facilities_guard"
  BEFORE UPDATE ON "facilities"
  FOR EACH ROW EXECUTE FUNCTION app_facility_guard();

-- ---------------------------------------------------------------------------------------------
-- Opening hours: ranges of one weekday never overlap. Changing them never touches bookings
-- already made.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app_facility_hours_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  PERFORM app_facility_lock(NEW."facility_id");
  IF EXISTS (SELECT 1 FROM "facility_opening_hours"
              WHERE "facility_id" = NEW."facility_id" AND "weekday" = NEW."weekday" AND "id" <> NEW."id"
                AND "opens_at" < NEW."closes_at" AND "closes_at" > NEW."opens_at") THEN
    RAISE EXCEPTION 'opening hours of one day cannot overlap' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    NEW."created_at" := now();
  ELSIF (NEW."organisation_id", NEW."property_id", NEW."facility_id", NEW."created_at")
        IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."facility_id", OLD."created_at") THEN
    RAISE EXCEPTION 'opening hours cannot move to another facility' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "facility_opening_hours_check"
  BEFORE INSERT OR UPDATE ON "facility_opening_hours"
  FOR EACH ROW EXECUTE FUNCTION app_facility_hours_check();

-- ---------------------------------------------------------------------------------------------
-- Closures: never over a live booking; lifted once, never edited or deleted.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app_facility_closure_insert() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  PERFORM app_facility_lock(NEW."facility_id");
  IF EXISTS (SELECT 1 FROM "facilities" WHERE "id" = NEW."facility_id" AND "status" = 'ARCHIVED') THEN
    RAISE EXCEPTION 'the facility is archived' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM "facility_bookings"
              WHERE "facility_id" = NEW."facility_id" AND "status" IN ('PENDING', 'CONFIRMED')
                AND "starts_at" < NEW."ends_at" AND "ends_at" > NEW."starts_at") THEN
    RAISE EXCEPTION 'cancel the bookings in that period before closing the facility'
      USING ERRCODE = 'check_violation';
  END IF;
  NEW."created_at" := now();
  NEW."lifted_at" := NULL;
  NEW."lifted_by_user_id" := NULL;
  RETURN NEW;
END
$$;

CREATE TRIGGER "facility_closures_insert"
  BEFORE INSERT ON "facility_closures"
  FOR EACH ROW EXECUTE FUNCTION app_facility_closure_insert();

CREATE FUNCTION app_facility_closure_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF OLD."lifted_at" IS NOT NULL OR NEW."lifted_by_user_id" IS NULL
     OR (NEW."organisation_id", NEW."property_id", NEW."facility_id", NEW."starts_at", NEW."ends_at",
         NEW."reason", NEW."created_by_user_id", NEW."created_at")
        IS DISTINCT FROM
        (OLD."organisation_id", OLD."property_id", OLD."facility_id", OLD."starts_at", OLD."ends_at",
         OLD."reason", OLD."created_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'closure % is never edited; lift it once and add another', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  NEW."lifted_at" := now();
  RETURN NEW;
END
$$;

CREATE TRIGGER "facility_closures_guard"
  BEFORE UPDATE ON "facility_closures"
  FOR EACH ROW EXECUTE FUNCTION app_facility_closure_guard();

-- ---------------------------------------------------------------------------------------------
-- Bookings
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app_facility_booking_insert() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  f record;
  tz text;
  local_start timestamp;
  local_end timestamp;
  day date;
  slot_seconds bigint;
  length_seconds bigint;
  taken bigint;
BEGIN
  PERFORM app_facility_lock(NEW."facility_id");
  SELECT * INTO f FROM "facilities" WHERE "id" = NEW."facility_id";
  IF f."status" <> 'ACTIVE' THEN
    RAISE EXCEPTION 'the facility is archived' USING ERRCODE = 'check_violation';
  END IF;
  SELECT "time_zone" INTO tz FROM "properties" WHERE "id" = NEW."property_id" AND "status" <> 'ARCHIVED';
  IF tz IS NULL THEN
    RAISE EXCEPTION 'the property is archived' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "units" WHERE "id" = NEW."unit_id" AND "status" = 'ACTIVE') THEN
    RAISE EXCEPTION 'the unit is archived' USING ERRCODE = 'check_violation';
  END IF;

  -- Owned by the database: whatever the client sent is replaced.
  NEW."created_at" := now();
  NEW."status" := CASE WHEN f."approval_required" THEN 'PENDING' ELSE 'CONFIRMED' END;
  NEW."status_note" := NULL;
  NEW."decided_by_user_id" := NULL;
  NEW."decided_at" := NULL;
  NEW."cancelled_at" := NULL;

  -- Whole slots inside one opening range of the local day, starting on a slot boundary.
  local_start := NEW."starts_at" AT TIME ZONE tz;
  local_end := NEW."ends_at" AT TIME ZONE tz;
  day := local_start::date;
  slot_seconds := f."slot_minutes"::bigint * 60;
  length_seconds := extract(epoch FROM local_end - local_start)::bigint;
  IF length_seconds <= 0 OR length_seconds % slot_seconds <> 0
     OR NOT EXISTS (SELECT 1 FROM "facility_opening_hours" h
                     WHERE h."facility_id" = f."id" AND h."weekday" = extract(isodow FROM day)
                       AND day + h."opens_at" <= local_start AND local_end <= day + h."closes_at"
                       AND extract(epoch FROM local_start - (day + h."opens_at"))::bigint % slot_seconds = 0) THEN
    RAISE EXCEPTION 'a booking is whole % minute slots inside the facility''s opening hours', f."slot_minutes"
      USING ERRCODE = 'check_violation';
  END IF;
  NEW."slot_count" := length_seconds / slot_seconds;
  IF NEW."slot_count" > f."max_slots_per_booking" THEN
    RAISE EXCEPTION 'a booking is at most % slots', f."max_slots_per_booking" USING ERRCODE = 'check_violation';
  END IF;

  IF NEW."starts_at" < now() + make_interval(mins => f."min_notice_minutes") THEN
    RAISE EXCEPTION 'book at least % minutes ahead', f."min_notice_minutes" USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."starts_at" > now() + make_interval(days => f."max_advance_days") THEN
    RAISE EXCEPTION 'book at most % days ahead', f."max_advance_days" USING ERRCODE = 'check_violation';
  END IF;

  IF EXISTS (SELECT 1 FROM "facility_closures"
              WHERE "facility_id" = f."id" AND "lifted_at" IS NULL
                AND "starts_at" < NEW."ends_at" AND "ends_at" > NEW."starts_at") THEN
    RAISE EXCEPTION 'the facility is closed then' USING ERRCODE = 'check_violation';
  END IF;

  IF f."max_upcoming_per_unit" IS NOT NULL AND (
       SELECT count(*) FROM "facility_bookings"
        WHERE "facility_id" = f."id" AND "unit_id" = NEW."unit_id"
          AND "status" IN ('PENDING', 'CONFIRMED') AND "ends_at" > now()) >= f."max_upcoming_per_unit" THEN
    RAISE EXCEPTION 'a unit may hold % upcoming bookings of this facility', f."max_upcoming_per_unit"
      USING ERRCODE = 'check_violation';
  END IF;

  -- The most bookings live at once during the new one: overlaps peak where one of them starts.
  SELECT max((SELECT count(*) FROM "facility_bookings" b
               WHERE b."facility_id" = f."id" AND b."status" IN ('PENDING', 'CONFIRMED')
                 AND b."starts_at" <= p.t AND b."ends_at" > p.t))
    INTO taken
    FROM (SELECT NEW."starts_at" AS t
          UNION
          SELECT b."starts_at" FROM "facility_bookings" b
           WHERE b."facility_id" = f."id" AND b."status" IN ('PENDING', 'CONFIRMED')
             AND b."starts_at" > NEW."starts_at" AND b."starts_at" < NEW."ends_at") p;
  IF taken >= f."capacity" THEN
    RAISE EXCEPTION 'that time is fully booked' USING ERRCODE = 'check_violation';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.facility_bookings:' || NEW."property_id"::text, 0));
  SELECT coalesce(max("booking_number"), 0) + 1 INTO NEW."booking_number"
    FROM "facility_bookings" WHERE "property_id" = NEW."property_id";
  RETURN NEW;
END
$$;

CREATE TRIGGER "facility_bookings_insert"
  BEFORE INSERT ON "facility_bookings"
  FOR EACH ROW EXECUTE FUNCTION app_facility_booking_insert();

CREATE FUNCTION app_facility_booking_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  transition text := OLD."status" || '>' || NEW."status";
BEGIN
  IF OLD."status" IN ('REJECTED', 'CANCELLED', 'COMPLETED', 'NO_SHOW') THEN
    RAISE EXCEPTION 'booking % is % and no longer changes', OLD."id", lower(replace(OLD."status"::text, '_', ' '))
      USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."facility_id", NEW."unit_id", NEW."booking_number",
      NEW."starts_at", NEW."ends_at", NEW."slot_count", NEW."purpose", NEW."booked_by_user_id", NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."facility_id", OLD."unit_id", OLD."booking_number",
      OLD."starts_at", OLD."ends_at", OLD."slot_count", OLD."purpose", OLD."booked_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'booking % cannot change place or time; cancel it and book again', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  PERFORM app_facility_lock(OLD."facility_id");
  NEW."decided_by_user_id" := OLD."decided_by_user_id";
  NEW."decided_at" := OLD."decided_at";
  NEW."cancelled_at" := OLD."cancelled_at";

  IF NEW."status" = OLD."status" THEN
    NEW."status_note" := OLD."status_note";
    RETURN NEW;
  END IF;
  IF transition NOT IN ('PENDING>CONFIRMED', 'PENDING>REJECTED', 'PENDING>CANCELLED',
                        'CONFIRMED>CANCELLED', 'CONFIRMED>COMPLETED', 'CONFIRMED>NO_SHOW') THEN
    RAISE EXCEPTION 'a booking cannot go from % to %', lower(OLD."status"::text), lower(replace(NEW."status"::text, '_', ' '))
      USING ERRCODE = 'check_violation';
  END IF;
  IF transition IN ('PENDING>REJECTED', 'CONFIRMED>CANCELLED') AND NEW."status_note" IS NULL THEN
    RAISE EXCEPTION 'give a reason to % this booking', CASE NEW."status" WHEN 'REJECTED' THEN 'reject' ELSE 'cancel' END
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" NOT IN ('REJECTED', 'CANCELLED') THEN
    NEW."status_note" := NULL;
  END IF;
  IF transition = 'PENDING>CONFIRMED' AND now() >= OLD."ends_at" THEN
    RAISE EXCEPTION 'this booking has already ended' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" IN ('COMPLETED', 'NO_SHOW') AND now() < OLD."starts_at" THEN
    RAISE EXCEPTION 'a booking is marked used or not used once it has started' USING ERRCODE = 'check_violation';
  END IF;

  IF OLD."status" = 'PENDING' AND NEW."status" IN ('CONFIRMED', 'REJECTED') THEN
    NEW."decided_by_user_id" := app_current_user_id();
    NEW."decided_at" := now();
    IF NEW."decided_by_user_id" IS NULL THEN
      RAISE EXCEPTION 'a booking is approved or rejected by a person' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW."status" = 'CANCELLED' THEN
    NEW."cancelled_at" := now();
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "facility_bookings_guard"
  BEFORE UPDATE ON "facility_bookings"
  FOR EACH ROW EXECUTE FUNCTION app_facility_booking_guard();

CREATE FUNCTION app_facility_booking_log() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW."status" IS DISTINCT FROM OLD."status" THEN
    INSERT INTO "facility_booking_events" ("id", "organisation_id", "property_id", "booking_id",
                                           "from_status", "to_status", "note", "actor_user_id")
    VALUES (gen_random_uuid(), NEW."organisation_id", NEW."property_id", NEW."id",
            CASE WHEN TG_OP = 'UPDATE' THEN OLD."status" END, NEW."status", NEW."status_note",
            app_current_user_id());
  END IF;
  RETURN NULL;
END
$$;

CREATE TRIGGER "facility_bookings_log"
  AFTER INSERT OR UPDATE ON "facility_bookings"
  FOR EACH ROW EXECUTE FUNCTION app_facility_booking_log();

-- ---------------------------------------------------------------------------------------------
-- Events: written only by the trigger above (pg_trigger_depth() > 1 while it runs); append-only.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app_facility_booking_event_insert() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF pg_trigger_depth() < 2 THEN
    RAISE EXCEPTION 'booking history is written by the database' USING ERRCODE = 'insufficient_privilege';
  END IF;
  NEW."created_at" := clock_timestamp();
  RETURN NEW;
END
$$;

CREATE TRIGGER "facility_booking_events_insert"
  BEFORE INSERT ON "facility_booking_events"
  FOR EACH ROW EXECUTE FUNCTION app_facility_booking_event_insert();

CREATE FUNCTION app_facility_booking_event_append_only() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  RAISE EXCEPTION 'booking history is append-only' USING ERRCODE = 'insufficient_privilege';
END
$$;

CREATE TRIGGER "facility_booking_events_append_only"
  BEFORE UPDATE OR DELETE ON "facility_booking_events"
  FOR EACH ROW EXECUTE FUNCTION app_facility_booking_event_append_only();
CREATE TRIGGER "facility_booking_events_no_truncate"
  BEFORE TRUNCATE ON "facility_booking_events"
  FOR EACH STATEMENT EXECUTE FUNCTION app_facility_booking_event_append_only();

-- ---------------------------------------------------------------------------------------------
-- Row-level security and grants. Only opening hours are deleted (replaced); history is never
-- updated.
-- ---------------------------------------------------------------------------------------------
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['facilities', 'facility_opening_hours', 'facility_closures', 'facility_bookings',
                           'facility_booking_events'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
  END LOOP;
  FOREACH t IN ARRAY ARRAY['facilities', 'facility_opening_hours', 'facility_closures', 'facility_bookings'] LOOP
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
END
$$;

REVOKE ALL ON "facilities", "facility_opening_hours", "facility_closures", "facility_bookings",
              "facility_booking_events" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "facilities", "facility_closures", "facility_bookings" TO veyra_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON "facility_opening_hours" TO veyra_app;
CREATE POLICY "facility_opening_hours_delete" ON "facility_opening_hours" FOR DELETE
  USING (organisation_id = app_current_organisation_id());
GRANT SELECT, INSERT ON "facility_booking_events" TO veyra_app;
GRANT USAGE ON SEQUENCE "facility_booking_events_sequence_seq" TO veyra_app;
